import React, { FunctionComponent } from 'react';
import { Field } from 'react-final-form';
import classNames from 'classnames';
import { defineMessages } from 'react-intl';
import { useTranslation } from '@getvim/translate';
import InputValidationMessage from '../../inputValidationMessage';
import LabeledInput from '../../labeledInput';
import es from './translations/es.json';

import './index.less';

const messages = defineMessages({
  invalid: {
    defaultMessage: ' is invalid',
    id: 'schemaValidator.invalid',
  },
});

export type TextualTimeInputProps = {
  id?: string;
  label?: string;
  name: string;
  className?: string;
  placeholder?: boolean;
  hideLabel?: boolean;
};

const DateInput: FunctionComponent<TextualTimeInputProps> = ({
  id,
  label,
  name,
  className,
  hideLabel,
  placeholder,
}) => {
  const intl = useTranslation({ es } as any);
  const timeFormat = 'HH:MM AM/PM';

  function isTimeInputValid(time: string): string | undefined {
    const formattedTimeRegex = /^(((0[0-9])|(1[0-2])):[0-5][0-9]) (AM|PM)$/i;
    const isTimeValid = !time || formattedTimeRegex.test(time);
    return !isTimeValid ? intl.formatMessage(messages.invalid) : undefined;
  }

  function onTextChange(
    newValue: string,
    previousValue: string,
    onChange: (event: any) => void,
  ): void {
    const value = newValue;
    const lastCharIndex = value.length - 1;
    let formattedDate = value;

    if (newValue.length > previousValue.length) {
      let newChar = value[lastCharIndex];

      if ([0, 1, 3, 4].includes(lastCharIndex)) {
        newChar = value[lastCharIndex]?.replace(/\D/g, '');

        if (lastCharIndex === 1) {
          newChar = `${newChar}:`;
        } else if (lastCharIndex === 4) {
          newChar = `${newChar} `;
        }
      } else if (
        (lastCharIndex === 2 && newChar !== ':') ||
        (lastCharIndex === 5 && newChar !== ' ') ||
        (lastCharIndex === 6 && !['A', 'P'].includes(newChar.toUpperCase())) ||
        (lastCharIndex === 7 && newChar.toUpperCase() !== 'M')
      ) {
        newChar = '';
      }

      const prev = newValue.substring(0, newValue.length - 1);
      formattedDate = `${prev}${newChar || ''}`;

      const numOfAllowedChars = timeFormat.length - 3;
      if (formattedDate.length > numOfAllowedChars) {
        formattedDate = formattedDate.substr(0, numOfAllowedChars);
      }
    }

    onChange(formattedDate);
  }

  return (
    <Field
      name={name}
      validate={isTimeInputValid}
      render={({ input, meta }) => (
        <div className="textual-time-input">
          <LabeledInput
            {...input}
            id={id}
            className={classNames(className, meta.error && meta.touched && 'has-error')}
            type="text"
            active={meta.active || !!input.value}
            placeholder={placeholder ? timeFormat : meta.active ? timeFormat : undefined}
            htmlFor={id}
            label={hideLabel ? undefined : label}
            onChange={(event) => onTextChange(event.target.value, input.value, input.onChange)}
            value={input.value}
          />
          {meta.touched && meta.error && (
            <InputValidationMessage>{label + meta.error}</InputValidationMessage>
          )}
        </div>
      )}
    />
  );
};

export default DateInput;
